SELECT CONCAT(YEAR(o.order_at), 'Q', QUARTER(o.order_at)), COUNT(o.promo_id) * 1.0 / COUNT(*) FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND ((o.order_at >= TIMESTAMP '2024-10-01 00:00:00' AND o.order_at < TIMESTAMP '2025-01-01 00:00:00') OR (o.order_at >= TIMESTAMP '2025-10-01 00:00:00' AND o.order_at < TIMESTAMP '2026-01-01 00:00:00')) GROUP BY 1
